{
  "checks": [
    {
      "problem": "链路明细里每个产品只展示开头几步的截图，后面的步骤没有图，读者无法在页面上核对问题清单和结论提到的那些界面。",
      "A": "解决",
      "B": "没解决"
    },
    {
      "problem": "问题清单、改进建议和链路明细之间没有互相引用的定位信息（问题编号、步骤号、屏名），读者要在几节之间来回数步骤、对编号才能把问题、建议和对应界面一一对上。",
      "A": "解决",
      "B": "部分解决"
    }
  ],
  "worse": [
    {
      "version": "B",
      "where": "链路明细",
      "why": "每个产品只排了前 4 步（好物只到第 4 步·上传凭证，集市只到第 4 步·确认退货，拾光只到第 4 步·上传凭证），好物第 5–7 步、集市第 5 步、拾光第 5–6 步仍然没有图，连三款的“提交成功”页都看不到；而这和本节标题“从进入退货到提交成功的完整步骤”以及分屏对比里写的 7/5/6 步对不上，读者想核对结论、共同模式或 P4（拾光第 5 步退款金额）时依旧无图可看。另外它把 4 张并排，每列说明更窄，部分图注文字被截断（如“图片上传、描述、上传…”），同一产品相邻步骤的说明也更难顺着读。"
    }
  ],
  "better": "A",
  "reason": "A 的链路明细把三款 App 的全部步骤（7/5/6 步）都配了截图，并在图注里直接带上“第 N 步·屏名·P1/P2/P3/P4”，读者从结论、问题清单或建议回到界面时一次就能定位；B 只排了每个产品的前 4 步，后几步无图，图注也只有步骤号和屏名、没有问题编号，仍要靠产品名加步骤数去对齐。",
  "next": [
    {
      "where": "共同模式",
      "task": "想验证“取件与时间合并”“凭证按原因出现”这类模式到底长什么样，去链路明细找对应界面",
      "why": "表里只写覆盖产品（集市、拾光），没有步骤号或屏名，读者还得自己数到集市第 2、第 3 步才能对上，结论表和明细之间少一层定位。"
    },
    {
      "where": "链路明细",
      "task": "对照同一产品相邻两步的界面（例如好物第 3 步退货原因和第 4 步上传凭证）",
      "why": "每行排 3 张，好物第 7 步单独掉到第三行，集市第 4、5 步另起一行，相邻步骤经常被行断开，读者要上下跨行、跨空白去找，前后对照不连贯。"
    }
  ]
}
